<span class="line"><span style="color:#FFAB70;">  type</span><span style="color:#F97583;">?:</span><span style="color:#9ECBFF;"> &#39;info&#39;</span><span style="color:#F97583;"> |</span><span style="color:#9ECBFF;"> &#39;success&#39;</span><span style="color:#F97583;"> |</span><span style="color:#9ECBFF;"> &#39;warning&#39;</span><span style="color:#F97583;"> |</span><span style="color:#9ECBFF;"> &#39;error&#39;</span><span style="color:#E1E4E8;">; </span><span style="color:#6A737D;">// 默认 &#39;info&#39;</span></span>
