<span class="line"><span style="color:#FFAB70;">  duration</span><span style="color:#F97583;">?:</span><span style="color:#79B8FF;"> number</span><span style="color:#E1E4E8;">;      </span><span style="color:#6A737D;">// 默认 3000，0 表示不自动关闭</span></span>
